def cap(s): return s[:1].upper()+s[1:]
def name(L,n): 
    if L=='en': return NM['en'][n]
    return (FR if L=='fr' else ES)[n][0]
def pair_label(L,a,b):
    if L=='en': return f"{cap(NM['en'][a])} to {NM['en'][b]}"
    if L=='fr': return f"{cap(FR[a][0])} {FR[b][1].replace('à ','vers ',1) if FR[b][1].startswith('à ') else ('vers '+FR[b][0])}"
    return f"{cap(ES[a][0])} {ES[b][1]}"
